blocks.value:
read(0, input, 0x400);

index = 0;
increment = 2;

while (true) {
    expected = ((pw[index] ^ 0x27) + increment) & 0xff;

    if (expected != input[index])
        fail();

    if (expected == '\n')
        success();

    index++;
    increment += 2;
}

